import 'package:flutter/material.dart';import '../../models/clothing_item.dart';import '../../services/api_service.dart';
class ItemDetailScreen extends StatelessWidget{const ItemDetailScreen({super.key,required this.item});final ClothingItem item;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(item.name),actions:[IconButton(onPressed:()async{final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:const Text('Delete item?'),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Delete'))]));if(ok==true){await ApiService().deleteClothing(item.id);if(c.mounted)Navigator.pop(c,true);}},icon:const Icon(Icons.delete_outline))]),body:ListView(padding:const EdgeInsets.all(20),children:[if(item.imageUrl?.isNotEmpty==true)ClipRRect(borderRadius:BorderRadius.circular(24),child:Image.network(item.imageUrl!,height:340,fit:BoxFit.cover)),const SizedBox(height:18),Text(item.name,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w500)),Text('${item.category} • ${item.color}'),const SizedBox(height:18),if(item.garmentType.isNotEmpty)Text('Type: ${item.garmentType}'),if(item.occasion.isNotEmpty)Text('Occasion: ${item.occasion}'),if(item.season.isNotEmpty)Text('Season: ${item.season}'),if(item.stylingNotes.isNotEmpty)...[const SizedBox(height:16),const Text('Styling notes',style:TextStyle(fontWeight:FontWeight.w500)),Text(item.stylingNotes)]]));}
